/**
 * One thing the agent is doing right now.
 */
public struct Activity: Equatable, Hashable {
    public var itemId: String
    /**
     * The subagent item it runs under, if not the main agent's.
     */
    public var parent: String?
    public var kind: ActivityKind
    /**
     * What it acts on, short; empty when there is nothing to say.
     */
    public var target: String
    /**
     * The English verb, for apps that don't localise.
     */
    public var label: String
    public var sinceMs: UInt64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(itemId: String, 
        /**
         * The subagent item it runs under, if not the main agent's.
         */parent: String?, kind: ActivityKind, 
        /**
         * What it acts on, short; empty when there is nothing to say.
         */target: String, 
        /**
         * The English verb, for apps that don't localise.
         */label: String, sinceMs: UInt64?) {
        self.itemId = itemId
        self.parent = parent
        self.kind = kind
        self.target = target
        self.label = label
        self.sinceMs = sinceMs
    }

    

    
}

