        return
            try Activity(
                itemId: FfiConverterString.read(from: &buf), 
                parent: FfiConverterOptionString.read(from: &buf), 
                kind: FfiConverterTypeActivityKind.read(from: &buf), 
                target: FfiConverterString.read(from: &buf), 
                label: FfiConverterString.read(from: &buf), 
                sinceMs: FfiConverterOptionUInt64.read(from: &buf)
        )
    }

    public static func write(_ value: Activity, into buf: inout [UInt8]) {
        FfiConverterString.write(value.itemId, into: &buf)
        FfiConverterOptionString.write(value.parent, into: &buf)
        FfiConverterTypeActivityKind.write(value.kind, into: &buf)
        FfiConverterString.write(value.target, into: &buf)
        FfiConverterString.write(value.label, into: &buf)
        FfiConverterOptionUInt64.write(value.sinceMs, into: &buf)
    }
}


