/**
 * An `acc_ui_render` or `acc_ui_ask` call the agent made.
 */
public struct AgentCall: Equatable, Hashable {
    public var itemId: String
    public var turn: UInt32
    /**
     * An ask whose answer the server still waits for.
     */
    public var running: Bool
    /**
     * `true` for `acc_ui_ask`, `false` for `acc_ui_render`.
     */
    public var isAsk: Bool
    public var spec: NormalizedSpec
    /**
     * For an ask, where its answer stands.
     */
    public var askState: AgentAskState?
    /**
     * Whether the user can still answer it (see `agentAnswer`).
     */
    public var awaitsAnswer: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(itemId: String, turn: UInt32, 
        /**
         * An ask whose answer the server still waits for.
         */running: Bool, 
        /**
         * `true` for `acc_ui_ask`, `false` for `acc_ui_render`.
         */isAsk: Bool, spec: NormalizedSpec, 
        /**
         * For an ask, where its answer stands.
         */askState: AgentAskState?, 
        /**
         * Whether the user can still answer it (see `agentAnswer`).
         */awaitsAnswer: Bool) {
        self.itemId = itemId
        self.turn = turn
        self.running = running
        self.isAsk = isAsk
        self.spec = spec
        self.askState = askState
        self.awaitsAnswer = awaitsAnswer
    }

    

    
}

