/**
 * One count in a [`Digest`]: a chip in a turn's digest row.
 */

public enum DigestPart: Equatable, Hashable {
    
    case edited(files: UInt32, created: UInt32, deleted: UInt32, added: UInt32, removed: UInt32
    )
    case read(files: UInt32
    )
    /**
     * Show it as a warning when `failed` is above 0.
     */
    case ran(commands: UInt32, failed: UInt32
    )
    /**
     * The last test run; show it as a warning when `failed` is above 0.
     */
    case tests(passed: UInt32, failed: UInt32, skipped: UInt32
    )
    case subagents(count: UInt32
    )
    case tools(count: UInt32
    )





}

#if compiler(>=6)
extension DigestPart: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDigestPart: FfiConverterRustBuffer {
    typealias SwiftType = DigestPart

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DigestPart {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .edited(files: try FfiConverterUInt32.read(from: &buf), created: try FfiConverterUInt32.read(from: &buf), deleted: try FfiConverterUInt32.read(from: &buf), added: try FfiConverterUInt32.read(from: &buf), removed: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 2: return .read(files: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .ran(commands: try FfiConverterUInt32.read(from: &buf), failed: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .tests(passed: try FfiConverterUInt32.read(from: &buf), failed: try FfiConverterUInt32.read(from: &buf), skipped: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .subagents(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 6: return .tools(count: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DigestPart, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .edited(files,created,deleted,added,removed):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(files, into: &buf)
            FfiConverterUInt32.write(created, into: &buf)
            FfiConverterUInt32.write(deleted, into: &buf)
            FfiConverterUInt32.write(added, into: &buf)
            FfiConverterUInt32.write(removed, into: &buf)
            
        
        case let .read(files):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(files, into: &buf)
            
        
        case let .ran(commands,failed):
